options.getOption:
// Observations by taxonomic group, in the colours of the map's dots, so the
// chart is also the map's legend. Clicking a bar filters the dashboard by that
// group (the `taxon` variable, which the map's filter, the counts and the
// tables follow); clicking it again clears it. Ctrl- or Shift-click adds or
// removes a group. The chart does not filter itself: the groups not picked
// stay in grey, for context. It follows the years and the month.
// @constants begin
const VAR = 'taxon';
const COLORS = {
  Aves: '#2f7ec4',
  Plantae: '#3f8f4a',
  Insecta: '#e0a02e',
  Reptilia: '#8c5a2b',
  Amphibia: '#63bfa0',
  Mammalia: '#b5443c',
  Arachnida: '#7a5aa8',
  Mollusca: '#d97fb0',
  Fungi: '#d9662a',
  Actinopterygii: '#3fb0c4',
  Protozoa: '#9aa63f',
  Other: '#8a8f96',
};
const UNIT = 'observations';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;
const CONTEXT = 'rgba(128, 128, 128, 0.22)';

const frame = context.panel.data.series.find((f) => f.refId === 'C');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const groups = col('grupo');
const counts = col('n').map((v) => (v == null ? null : Number(v)));

// The variable as a list. "All" expands to every group: that is no selection.
const read = () => {
  let values;
  try {
    values = [JSON.parse(context.grafana.replaceVariables('${' + VAR + ':json}'))].flat();
  } catch (e) {
    values = [];
  }
  const picked = values.filter((v) => groups.includes(v));
  return picked.length === 0 || groups.every((g) => picked.includes(g)) || values.includes('$__all') ? [] : picked;
};
const picked = read();

chart.off('click');
chart.on('click', (event) => {
  const id = groups[event.dataIndex];
  const now = read();
  const add = event.event && event.event.event && (event.event.event.ctrlKey || event.event.event.metaKey || event.event.event.shiftKey);
  let next;
  if (add) {
    next = now.includes(id) ? now.filter((g) => g !== id) : [...now, id];
  } else {
    next = now.length === 1 && now[0] === id ? [] : [id];
  }
  location.partial({ ['var-' + VAR]: next.length ? next : '$__all' }, true);
});

const fmt = (v) => (v == null ? '–' : v >= 1000 ? `${(v / 1000).toFixed(v >= 10000 ? 0 : 1)}k` : String(v));

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 40, top: 8, bottom: 8, containLabel: true },
  tooltip: {
    trigger: 'item',
    formatter: (p) => `<b>${groups[p.dataIndex]}</b><br/>${(counts[p.dataIndex] ?? 0).toLocaleString('en')} ${UNIT}<br/><i>Click to filter, again to clear</i>`,
  },
  xAxis: { type: 'value', show: false },
  yAxis: {
    type: 'category',
    inverse: true,
    data: groups,
    axisTick: { show: false },
    axisLine: { show: false },
    axisLabel: { color: (v) => (picked.length && !picked.includes(v) ? muted : text), fontSize: 11 },
  },
  series: [
    {
      type: 'bar',
      barWidth: '72%',
      cursor: 'pointer',
      data: counts.map((v, i) => ({
        value: v,
        itemStyle: {
          color: picked.length && !picked.includes(groups[i]) ? CONTEXT : COLORS[groups[i]] ?? muted,
          borderRadius: [0, 3, 3, 0],
        },
      })),
      label: { show: true, position: 'right', color: muted, fontSize: 10, formatter: (p) => fmt(p.value) },
    },
  ],
};

