options.getOption:
// Observations per year, from 2016 on. Dragging across the bars sets the
// dashboard's years ("From year" and "To year"); the counts, the map's dots,
// the other charts and the tables follow. Clearing the brush (the toolbox's
// bin) goes back to the whole history. Grey is every observation in the drawn
// area; colour is what the group and month filters leave. The chart does not
// filter itself by year, so the whole range stays in view.
// Adapted from assets/brush-histogram.js for whole years, inclusive at both
// ends, and for variables whose "no filter" value is not empty (1900 and 9999,
// which the ArcGIS where clauses compare as plain numbers).
// @constants begin
const LO = 'desdeAnio';
const HI = 'hastaAnio';
const NONE = ['1900', '9999'];
const UNIT = 'observations';
const COLOR = '#2f7ec4';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;

const frameOf = (refId) => context.panel.data.series.find((f) => f.refId === refId);
const pairs = (refId) => {
  const frame = frameOf(refId);
  if (!frame) {
    return new Map();
  }
  const bins = frame.fields.find((f) => f.name === 'bin')?.values ?? [];
  const counts = frame.fields.find((f) => f.name === 'n')?.values ?? [];
  return new Map(Array.from(bins, (b, i) => [Number(b), counts[i] == null ? null : Number(counts[i])]));
};
const all = pairs('all');
const selected = pairs('selected');
const years = [...all.keys()].sort((a, b) => a - b);
const first = years[0];
const last = years[years.length - 1];

// A bar stands at its year, from year - 0.5 to year + 0.5. A brush takes the
// years whose bar it covers at least half of; it is redrawn over whole bars.
const snap = (range) => {
  const a = Math.min(...range);
  const b = Math.max(...range);
  let lo = Math.ceil(a);
  let hi = Math.floor(b);
  if (hi < lo) {
    lo = hi = Math.round((a + b) / 2); // a brush inside one bar takes that year
  }
  return [Math.max(lo, first), Math.min(hi, last)];
};
const drawBrush = (range) =>
  chart.dispatchAction({ type: 'brush', areas: range ? [{ brushType: 'lineX', xAxisIndex: 0, coordRange: range }] : [] });
const publish = (lo, hi) => {
  location.partial({ ['var-' + LO]: String(lo), ['var-' + HI]: String(hi) }, true);
};

chart.off('brushEnd');
chart.off('brush');
chart.on('brushEnd', (event) => {
  const area = event.areas[0];
  if (!area || !area.coordRange || !years.length) {
    publish(NONE[0], NONE[1]);
    return;
  }
  const [y0, y1] = snap(area.coordRange);
  // The last bar is the year in course: reaching it means "up to now".
  publish(y0, y1 === last ? NONE[1] : y1);
  setTimeout(() => drawBrush([y0 - 0.5, y1 + 0.5]), 0);
});
chart.on('brush', (event) => {
  if (event.command === 'clear') {
    publish(NONE[0], NONE[1]);
  }
});

// Every redraw wipes the brush: draw it back from the variables, which is
// also how a shared link (or the "From year" dropdown) shows its range.
const lo = parseInt(context.grafana.replaceVariables('${' + LO + '}'), 10);
const hi = parseInt(context.grafana.replaceVariables('${' + HI + '}'), 10);
const filtered = years.length && ((Number.isFinite(lo) && lo > first) || (Number.isFinite(hi) && hi < last));
const range = filtered
  ? [Math.max(Number.isFinite(lo) ? lo : first, first) - 0.5, Math.min(Number.isFinite(hi) ? hi : last, last) + 0.5]
  : undefined;
setTimeout(() => {
  chart.dispatchAction({ type: 'takeGlobalCursor', key: 'brush', brushOption: { brushType: 'lineX', brushMode: 'single' } });
  if (range && range[0] <= range[1]) {
    drawBrush(range);
  }
}, 0);

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 30, bottom: 4, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const rows = items.map((it) => `${it.marker}${it.seriesName}: <b>${(it.value[1] ?? 0).toLocaleString('en')}</b>`).join('<br/>');
      return `${items[0].value[0]} · ${UNIT}<br/>${rows}`;
    },
  },
  toolbox: {
    right: 8,
    top: 0,
    itemSize: 14,
    feature: { brush: { type: ['lineX', 'clear'], title: { lineX: 'Select years', clear: 'All history' } } },
  },
  brush: {
    xAxisIndex: 0,
    seriesIndex: [1],
    brushType: 'lineX',
    brushMode: 'single',
    transformable: true,
    brushStyle: { color: 'rgba(128, 128, 128, 0.12)', borderColor: muted, borderWidth: 1 },
    outOfBrush: { colorAlpha: 0.25 },
  },
  xAxis: {
    type: 'value',
    min: first - 0.5,
    max: last + 0.5,
    minInterval: 1,
    splitLine: { show: false },
    axisTick: { show: false },
    axisLabel: { color: muted, fontSize: 10, showMinLabel: false, showMaxLabel: false, formatter: (v) => (Number.isInteger(v) ? String(v) : '') },
  },
  yAxis: {
    type: 'value',
    axisLabel: { color: muted, fontSize: 10, formatter: (v) => (v >= 1000 ? `${v / 1000}k` : v) },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  series: [
    { name: 'All groups', type: 'bar', data: years.map((y) => [y, all.get(y)]), barWidth: '80%', silent: true, itemStyle: { color: 'rgba(128, 128, 128, 0.22)' } },
    { name: 'Filtered', type: 'bar', data: years.map((y) => [y, selected.get(y) ?? 0]), barWidth: '80%', barGap: '-100%', itemStyle: { color: COLOR } },
  ],
};

