options.getOption:
// Observations by month of the year: when people go out and photograph, not
// how abundant life is. Clicking a month filters the dashboard by it (the
// hidden `mes` variable, which the counts, the map's dots, the other charts
// and the tables follow); clicking it again clears it. Ctrl- or Shift-click
// adds or removes a month. The chart does not filter itself: the months not
// picked stay in grey. It follows the group and the years.
// @constants begin
const VAR = 'mes';
const COLOR = '#e0a02e';
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const UNIT = 'observations';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;
const CONTEXT = 'rgba(128, 128, 128, 0.22)';

const frame = context.panel.data.series.find((f) => f.refId === 'F');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const byMonth = new Map(col('mes').map((m, i) => [String(Number(m)), Number(col('n')[i])]));
const ids = MONTHS.map((_, i) => String(i + 1));
const counts = ids.map((m) => byMonth.get(m) ?? 0);

// The variable as a list. "All" expands to the twelve months: no selection.
const read = () => {
  let values;
  try {
    values = [JSON.parse(context.grafana.replaceVariables('${' + VAR + ':json}'))].flat().map(String);
  } catch (e) {
    values = [];
  }
  const picked = values.filter((v) => ids.includes(v));
  return picked.length === 0 || picked.length === ids.length || values.includes('$__all') ? [] : picked;
};
const picked = read();

chart.off('click');
chart.on('click', (event) => {
  const id = ids[event.dataIndex];
  const now = read();
  const add = event.event && event.event.event && (event.event.event.ctrlKey || event.event.event.metaKey || event.event.event.shiftKey);
  let next;
  if (add) {
    next = now.includes(id) ? now.filter((m) => m !== id) : [...now, id];
  } else {
    next = now.length === 1 && now[0] === id ? [] : [id];
  }
  location.partial({ ['var-' + VAR]: next.length && next.length < ids.length ? next : '$__all' }, true);
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 8, top: 10, bottom: 4, containLabel: true },
  tooltip: {
    trigger: 'item',
    formatter: (p) => `<b>${MONTHS[p.dataIndex]}</b><br/>${counts[p.dataIndex].toLocaleString('en')} ${UNIT}<br/><i>Click to filter, again to clear</i>`,
  },
  xAxis: {
    type: 'category',
    data: MONTHS,
    axisTick: { show: false },
    axisLabel: { fontSize: 10, interval: 0, color: (v, i) => (picked.length && !picked.includes(ids[i]) ? muted : text) },
  },
  yAxis: {
    type: 'value',
    axisLabel: { color: muted, fontSize: 10, formatter: (v) => (v >= 1000 ? `${v / 1000}k` : v) },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  series: [
    {
      type: 'bar',
      barWidth: '72%',
      cursor: 'pointer',
      data: counts.map((v, i) => ({ value: v, itemStyle: { color: picked.length && !picked.includes(ids[i]) ? CONTEXT : COLOR, borderRadius: [2, 2, 0, 0] } })),
    },
  ],
};

